-- Unit-scoped B2B analytics and fleet counts. Unit scope is optional; org admins can cross units.
create function private.reda_unit_allowed(p_unit uuid)returns boolean language sql stable security definer set search_path='' as $$select p_unit is null or private.reda_can_manage_units(private.reda_request_organization(),private.reda_live_actor()) or exists(select 1 from public.reda_unit_memberships m where m.unit_id=p_unit and m.organization_id=private.reda_request_organization() and m.user_id=private.reda_live_actor() and m.status='active')$$;
create function private.reda_unit_fleet(p_unit uuid default null)returns jsonb language plpgsql stable security definer set search_path='' as $$declare org uuid:=private.reda_request_organization();begin if not private.reda_is_clinician_aal2() or not private.reda_unit_allowed(p_unit) then raise exception using errcode='42501',message='Enheten är inte tillgänglig.';end if;return (with patients as(select p.id from public.reda_patients p where p.organization_id=org and p.status='active' and (p_unit is null or p.unit_id=p_unit)),frames as(select distinct on(f.patient_id)f.patient_id,f.execution,f.status from public.reda_progression_frames f join patients p on p.id=f.patient_id where f.status='approved' order by f.patient_id,f.approved_at desc),cases as(select patient_id,count(*)n from public.reda_review_cases c join patients p on p.id=c.patient_id where c.status<>'resolved'group by patient_id)select jsonb_build_object('total',count(*),'autonomous',count(*)filter(where f.status='approved'and f.execution='automatic'and coalesce(c.n,0)=0),'review',count(*)filter(where coalesce(c.n,0)>0),'shadow',count(*)filter(where f.status='approved'and f.execution='shadow'),'unframed',count(*)filter(where f.patient_id is null))from patients p left join frames f on f.patient_id=p.id left join cases c on c.patient_id=p.id);end$$;
create function public.reda_unit_fleet(p_unit uuid default null)returns jsonb language sql stable security invoker set search_path='' as $$select private.reda_unit_fleet(p_unit)$$;
revoke all on function private.reda_unit_allowed(uuid),private.reda_unit_fleet(uuid),public.reda_unit_fleet(uuid) from public,anon,authenticated;grant execute on function private.reda_unit_allowed(uuid),private.reda_unit_fleet(uuid),public.reda_unit_fleet(uuid) to authenticated;
